# LSM: memtable -> flush -> leveled SSTables; reads merge newest-first
mem, levels = {}, [[], []]  # L0, L1 (each: sorted runs)

def put(k, v):
    mem[k] = v
    if len(mem) >= 4:  # memtable full: flush sorted run to L0
        levels[0].append(sorted(mem.items()))
        mem.clear()

def get(k):
    if k in mem:
        return mem[k], 'memtable'
    for li, runs in enumerate(levels):
        for run in reversed(runs):  # newest run first
            for kk, vv in run:
                if kk == k:
                    return vv, 'L%d' % li
    return None, 'miss'

for i in range(10):
    put('k%d' % i, i)
print('get k3:', get('k3'))
print('get k9:', get('k9'), '(still in memtable)')
print('writes sequential; reads merge across levels')

import bisect

mem, wal = [], []  # sorted list stands in for the skip list

def put(k, v):
    wal.append((k, v))          # durability first
    i = bisect.bisect_left([kk for kk, _ in mem], k)
    if i < len(mem) and mem[i][0] == k:
        mem[i] = (k, v)
    else:
        mem.insert(i, (k, v))

def flush():
    run, mem[:] = list(mem), []  # immutable snapshot -> SSTable
    return run

for k, v in [('b', 2), ('a', 1), ('c', 3), ('a', 10)]:
    put(k, v)
print('memtable:', mem, '(sorted; WAL has', len(wal), 'entries for replay)')
print('flushed run:', flush())

# NRT: tiny segments searchable instantly, merged in background
segments, big = [], {}

def add(doc):
    segments.append(doc)  # searchable immediately
    if len(segments) >= 3:
        big.update({d['id']: d for d in segments})  # background merge
        segments.clear()

def search(q):
    return [d for d in list(big.values()) + segments if q in d['text']]

add({'id': 1, 'text': 'hello world'})
print('search right after write:', search('hello'), '(visible before any merge)')
add({'id': 2, 'text': 'hello again'}); add({'id': 3, 'text': 'hi'})
print('after merge, segments:', len(segments), '| big index:', len(big))

# log-based CDC: the WAL becomes a change stream; the index follows
wal = [
    ('ins', 'a', None, 1, 1), ('ins', 'b', None, 2, 2),
    ('upd', 'a', 1, 10, 3), ('del', 'b', 2, None, 4),
]
index = {}
for op, k, before, after, seq in wal:  # the change stream
    if op == 'del':
        index.pop(k, None)
    else:
        index[k] = after
    print('seq %d: %-4s %s -> index %s' % (seq, op, k, index))
print('no polling, no triggers: the log IS the stream (ordered, complete)')

# manifest = atomic commit point; WAL replay bounded by last flush
manifest = {'sstables': ['s1', 's2'], 'flushed_through': 100}
wal = [(101, 'a', 1), (102, 'b', 2), (103, 'x', 'CORRUPT-TAIL')]
mem = {}

for seq, k, v in wal:
    if v == 'CORRUPT-TAIL':
        print('seq %d: checksum failed -> stop (torn tail discarded)' % seq)
        break
    if seq > manifest['flushed_through']:
        mem[k] = v
print('recovered memtable:', mem, '| SSTables:', manifest['sstables'])
print('old files deleted only after the NEW manifest is durable')
